    </div>
  </div>
</div>',
      title = 'Test the Full Payment Journey',
      lesson_number = 6,
      sort_order = 6,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Test the Full Payment Journey';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Test the Full Payment Journey

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 11 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 11 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'test-full-payment-journey' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson test-full-payment-journey not found in module 11';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does PAY FIRST stand for?', 
    '["Pay All Your Fees Immediately, Receive Service Today","Product, Account, Your buyer, Figures, Instructions, Run a test, Screen check, Track the result","Purchase All Your Financial Items, Record Sales Transactions","Process All Yearly Financial Income Reports Swiftly Today"]'::jsonb,
    'Product, Account, Your buyer, Figures, Instructions, Run a test, Screen check, Track the result',
    'PAY FIRST stands for: Product, Account, Your buyer, Figures, Instructions, Run a test, Screen check, Track the result. Use this before any payment request goes live.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you test in a private browser window?', 
    '["It is faster","It shows more closely what a buyer who is not signed in will see","It saves money","It is required by law"]'::jsonb,
    'It shows more closely what a buyer who is not signed in will see',
    'A private browser window shows what a buyer who is not signed into your account will see, giving you a more accurate test of the customer experience.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do after a test passes?', 
    '["Immediately switch everything to live mode","Confirm the live provider connection separately before switching to live mode","Delete the test data","Never use live mode"]'::jsonb,
    'Confirm the live provider connection separately before switching to live mode',
    'After a test passes, confirm the live provider connection separately. Test and live mode may use different provider settings. Switch only the intended checkout to live mode and verify again.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
